        "everyday|6:1|0|w0": "फलाट",
        "everyday|6:1|0|w1": "बर्थ",
        "everyday|6:1|0|w2": "प्रतीक्षा यादी",
        "everyday|6:1|0|w3": "आरक्षण",
        "everyday|6:1|0|w4": "भाडं",
        "everyday|6:1|0|w5": "डबा",
        "everyday|6:1|1|p0": "चालुक्य एक्सप्रेस कोणत्या फलाटावरून सुटते?",
        "everyday|6:1|1|p1": "मला खालचा बर्थ हवा आहे, कारण माझ्या वडिलांना वर चढणं जड जातं.",
        "everyday|6:1|1|p2": "आमची तिकिटं अजून प्रतीक्षा यादीत आहेत, त्यामुळे कदाचित आम्हाला जागा मिळणार नाहीत.",
        "everyday|6:1|1|p3": "दिवाळीच्या किमान एक महिना आधी तुम्ही आरक्षण करायला हवं.",
        "everyday|6:1|1|p4": "पुण्यापर्यंत स्लीपर डब्याचं भाडं साधारण सहाशे रुपये आहे.",
        "everyday|6:1|2|w0": "उशीर",
        "everyday|6:1|2|w1": "रद्दीकरण",
        "everyday|6:1|2|w2": "चौकशी",
        "everyday|6:1|2|w3": "सामान",
        "everyday|6:1|2|w4": "वेळापत्रक",
        "everyday|6:1|2|w5": "हमाल",
        "everyday|6:1|3|p0": "दिल्लीजवळ दाट धुक्यामुळे चार तासांचा उशीर आहे.",
        "everyday|6:1|3|p1": "दोन दिवसांपेक्षा जास्त आधी रद्द केलं, तर रद्दीकरण शुल्क कमी असतं.",
        "everyday|6:1|3|p2": "बस रद्द झाली, म्हणून मी पैसे परत मागायला चौकशी खिडकीवर गेलो.",
        "everyday|6:1|3|p3": "ती घोषणा ऐकलीत का? आपल्याला आपलं सामान पाच नंबर फलाटावर न्यायचं आहे.",
        "everyday|6:1|3|p4": "वेळापत्रकाप्रमाणे म्हैसूरला जाणारी शेवटची बस दहा वाजता सुटते.",
        "everyday|6:1|4|title": "अगदी वेळेवर",
        "everyday|6:1|4|text": "आशा तिच्या बहिणीच्या लग्नासाठी हुबळीहून पुण्याला चालली होती. तिने दोन महिने आधीच आरक्षण केलं होतं आणि तिला एस-4 डब्यात खालचा बर्थ मिळाला होता. स्टेशनवर घोषणा झाली की गाडीला तीन तासांचा उशीर आहे. आशाने फोनवर बसचं वेळापत्रक पाहिलं आणि पुण्याला लवकर पोहोचणारी एक बस शोधली. तिने ट्रेनचं तिकीट ऑनलाइन रद्द केलं, आणि दोन दिवसांत पैसे तिच्या खात्यात परत आले. एका हमालाने थोड्याशा पैशांत तिच्या जड बॅगा बसस्टँडपर्यंत नेल्या. ती अगदी मेहंदीच्या वेळेवर पुण्याला पोहोचली.",
        "everyday|6:1|4|q0": "आशा पुण्याला का चालली होती?",
        "everyday|6:1|4|q0o0": "बहिणीच्या लग्नासाठी",
        "everyday|6:1|4|q0o1": "नोकरीच्या मुलाखतीसाठी",
        "everyday|6:1|4|q0o2": "कॉलेजच्या सहलीसाठी",
        "everyday|6:1|4|q0o3": "डॉक्टरकडे जाण्यासाठी",
        "everyday|6:1|4|q1": "गाडीला किती उशीर होता?",
        "everyday|6:1|4|q1o0": "तीन तास",
