        "opinions|2:1|4|q2": "शिक्षकांनी त्यांना कोणत्या योजनेवर एकमत करायला मदत केली?",
        "opinions|2:1|4|q2o0": "सकाळी हंपी, दुपारी नदीकाठी आराम",
        "opinions|2:1|4|q2o1": "एक दिवस गोकर्ण आणि एक दिवस हंपी",
        "opinions|2:1|4|q2o2": "हासनमध्येच राहून संग्रहालय पाहणं",
        "opinions|2:1|4|q2o3": "फक्त रात्री हंपी पाहणं",
        "opinions|2:1|5|title": "कॉलेज महोत्सवाचं नियोजन",
        "opinions|2:1|5|scenario": "मंगळुरूमधल्या एका कॉलेजच्या महोत्सव समितीतले दोन विद्यार्थी, पूजा आणि समीर, पैसे कसे खर्च करायचे यावर असहमत आहेत.",
        "opinions|2:1|5|l0": "समीर, मी ऐकलं की तुला कॉलेज महोत्सवाला एखाद्या फिल्म स्टारला बोलवायचं आहे. हे खरं आहे का?",
        "opinions|2:1|5|l1": "हो! मोठं नाव असलं की प्रचंड गर्दी होईल. तुला नाही वाटत?",
        "opinions|2:1|5|l2": "काही प्रमाणात, हो. पण आदरपूर्वक सांगते, त्या स्टारची फी आपले अर्धे पैसे खाऊन टाकेल.",
        "opinions|2:1|5|l3": "हा योग्य मुद्दा आहे. तरीही, स्टारशिवाय महोत्सव जरा साधारण वाटतो.",
        "opinions|2:1|5|l4": "मी नम्रपणे असहमत आहे. गेल्या वर्षी उडुपीचा यक्षगान संच हा महोत्सवाचा सगळ्यात छान भाग होता.",
        "opinions|2:1|5|l5": "हं, त्या कार्यक्रमाबद्दल मी पूर्णपणे सहमत आहे. शेवटी सगळे नाचत होते.",
        "opinions|2:1|5|l6": "मग त्यांनाच पुन्हा का बोलवू नये, आणि उरलेले पैसे चांगल्या जेवणावर आणि दिव्यांवर खर्च करू?",
        "opinions|2:1|5|l7": "ठीक आहे, तू माझं मन वळवलंस. मी पुनर्विचार करतो आणि उद्या समितीशी बोलतो.",
        "opinions|2:1|5|l8": "इतक्या खुल्या मनाने विचार केल्याबद्दल धन्यवाद. मला माहीत आहे ती तुझी आवडती कल्पना होती.",
        "opinions|2:1|5|l9": "बरं, कोणता फिल्म स्टार सगळ्यात भारी आहे, यावर आपण आपले मतभेद मान्य करू शकतो!",
        "opinions|2:1|5|q0": "समीरला महोत्सवासाठी काय हवं होतं?",
        "opinions|2:1|5|q0o0": "एका फिल्म स्टारला बोलवायचं",
