        "opinions|3:1|1|p1": "माझ्या बालपणी आम्ही अंधार पडेपर्यंत शेतात खेळायचो.",
        "opinions|3:1|1|p2": "शाळेतल्या माझ्या पहिल्या दिवसाची ठळक आठवण अजूनही माझ्या मनात आहे.",
