        "opinions|3:1|3|p0": "बेळगावमधले माझे शाळेचे दिवस हे माझ्या आयुष्यातली सगळ्यात आनंदी वर्षं होती.",
        "opinions|3:1|3|p1": "आंतरशालेय प्रश्नमंजूषा जिंकणं हा आमच्या संपूर्ण वर्गासाठी एक अविस्मरणीय क्षण होता.",
        "opinions|3:1|3|p2": "त्या परीक्षेत नापास होणं हा माझ्या आयुष्याला कलाटणी देणारा क्षण होता; त्यानंतर मी मन लावून अभ्यास करू लागलो.",
        "opinions|3:1|3|p3": "आमच्या वसतिगृहाच्या वॉर्डनना आमच्या सगळ्या खोड्या माहीत होत्या, पण ते न पाहिल्यासारखं करायचे.",
        "opinions|3:1|3|p4": "माझ्या आवडत्या शिक्षकांची आठवण म्हणून मी हे जुनं फाउंटन पेन जपून ठेवलं आहे.",
        "opinions|3:1|4|title": "कोडगूमधली पावसाळी संध्याकाळ",
        "opinions|3:1|4|text": "श्रेया कोडगूमधल्या एका छोट्या गावात मोठी झाली, जिथे तिचं कुटुंब कॉफीची शेती करायचं. तिला तिचं बहुतेक बालपण फक्त अंधुकसं आठवतं, पण एक दिवस अजूनही तिच्या मनात ठळक आहे. ती दहा वर्षांची असताना मुसळधार पावसाने नदीला पूर आला, आणि शाळेची बस पूल ओलांडू शकली नाही. मुलं थंडीत कित्येक तास वाट पाहत राहिली, शेवटी पोन्नप्पा नावाचा एक शेतकरी त्याचा ट्रॅक्टर घेऊन आला. त्याने एका वेळी दोन-तीन अशी सगळी तीस मुलं पाण्यातून पलीकडे नेली. त्याने दिलेला छोटा टॉवेल श्रेयाने अजूनही आठवण म्हणून जपून ठेवला आहे. जोराचा पाऊस पडला की तिला अचानक त्या संध्याकाळची आठवण येते. तिच्यासाठी तो कलाटणी देणारा क्षण होता: त्याच दिवशी तिने ठरवलं की तीसुद्धा आयुष्यभर लोकांना मदत करेल.",
        "opinions|3:1|4|q0": "शाळेची बस मुलांना घरी का नेऊ शकली नाही?",
        "opinions|3:1|4|q0o0": "नदीला पूर आला आणि बस पूल ओलांडू शकली नाही",
