        "opinions|3:1|5|title": "आजोबांचे शाळेचे दिवस",
        "opinions|3:1|5|scenario": "वर्गाच्या प्रकल्पासाठी अनन्या मंड्यात तिच्या आजोबांशी, नारायण यांच्याशी, त्यांच्या शाळेच्या दिवसांबद्दल बोलते.",
        "opinions|3:1|5|l0": "आजोबा, माझ्या प्रकल्पासाठी सांगाल का, तुम्ही लहान असताना शाळा कशी होती?",
        "opinions|3:1|5|l1": "अगं, ते दिवस वेगळेच होते. आम्ही रोज चार किलोमीटर चालत शाळेत जायचो.",
        "opinions|3:1|5|l2": "चार किलोमीटर! तुमच्याकडे बस किंवा सायकल नव्हती का?",
        "opinions|3:1|5|l3": "आमच्या गावात कोणाकडेच सायकल नव्हती. आम्ही अनवाणी चालायचो आणि वाटेत गाणी म्हणायचो.",
        "opinions|3:1|5|l4": "त्या दिवसांतली तुमची सगळ्यात ठळक आठवण कोणती?",
        "opinions|3:1|5|l5": "ज्या दिवशी मुख्याध्यापकांनी मला त्यांच्या झाडावरचे आंबे चोरताना पकडलं तो दिवस. त्यांचा चेहरा मला अजूनही दिसतो!",
        "opinions|3:1|5|l6": "आजोबा, तुम्ही अशा खोड्या करायचात हे मला माहीतच नव्हतं! मग पुढे काय झालं?",
        "opinions|3:1|5|l7": "त्यांनी मला पूर्ण महिनाभर त्यांच्या बागेला पाणी घालायला लावलं. खरं सांगायचं तर, तो कलाटणी देणारा क्षण होता; मला झाडांचा लळा लागला.",
        "opinions|3:1|5|l8": "तुम्हाला कधी त्या दिवसांची ओढ वाटते का?",
        "opinions|3:1|5|l9": "बऱ्याचदा. आयुष्य कठीण होतं, पण अगदी थोड्यात आम्ही आनंदी होतो.",
        "opinions|3:1|5|q0": "आजोबा शाळेत कसे जायचे?",
        "opinions|3:1|5|q0o0": "ते चार किलोमीटर चालत जायचे",
