        "opinions|4:1|0|w4": "मनाचे मांडे",
        "opinions|4:1|0|w5": "सोडून देणे",
        "opinions|4:1|1|p0": "मी आजोबांबरोबर आणखी वेळ घालवला असता तर किती बरं झालं असतं.",
        "opinions|4:1|1|p1": "माझी एकच खंत आहे की मी कधीच पोहायला शिकलो नाही.",
        "opinions|4:1|1|p2": "मी आईचं ऐकलं असतं तर आता असा पावसात अडकलो नसतो.",
        "opinions|4:1|1|p3": "मागे वळून पाहताना वाटतं, मी कॉमर्सऐवजी सायन्स निवडायला हवं होतं.",
        "opinions|4:1|1|p4": "प्रत्येकाला दुसरी संधी मिळायलाच हवी, त्यामुळे भूतकाळ सोडून द्या आणि पुन्हा सुरुवात करा.",
        "opinions|4:1|2|w0": "आतुरतेने वाट पाहणे",
        "opinions|4:1|2|w1": "ओढ",
        "opinions|4:1|2|w2": "आशावादी",
