        "opinions|4:1|2|w4": "दिवास्वप्न",
        "opinions|4:1|2|w5": "आशेचा किरण",
        "opinions|4:1|3|p0": "या दिवाळीत वाराणसीत माझ्या चुलत भावंडांना भेटण्याची मी खूप आतुरतेने वाट पाहतोय.",
        "opinions|4:1|3|p1": "दुबईत दोन वर्षं राहिल्यावर त्याला त्याच्या गावाची तीव्र ओढ वाटू लागली.",
        "opinions|4:1|3|p2": "उद्या निकाल लागणार आहे, पण मी बराच आशावादी आहे, देव करो!",
        "opinions|4:1|3|p3": "सुट्ट्यांची दिवास्वप्नं बघणं थांबव आणि आधी तुझा प्रकल्प पूर्ण कर.",
        "opinions|4:1|3|p4": "सामना हरल्याचं दुःख झालं, पण आशेचा किरण म्हणजे आम्ही खूप काही शिकलो.",
        "opinions|4:1|4|title": "पासष्टाव्या वर्षी दुसरी संधी",
        "opinions|4:1|4|text": "व्यंकटेश पासष्ट वर्षांचे आहेत आणि म्हैसूरमध्ये राजवाड्याजवळ एकटे राहतात. तरुणपणी त्यांना चेन्नईत संगीत शिकण्याची संधी मिळाली होती, पण त्याऐवजी त्यांनी बँकेतली सुरक्षित नोकरी निवडली. कित्येक वर्षं ते स्वतःला सांगत राहिले की त्याने काही फरक पडत नाही, पण मनाच्या कोपऱ्यात एक शांत खंत नेहमी होती. 'मी जरा धाडस केलं असतं तर,' ते त्यांची मुलगी लक्ष्मी हिला म्हणायचे. गेल्या वर्षी लक्ष्मीला मोठ्यांसाठीचा संध्याकाळचा एक संगीत वर्ग सापडला आणि वाढदिवसाचं सरप्राइज म्हणून तिने त्यांचं नाव त्यात नोंदवलं. सुरुवातीला ते हसले आणि म्हणाले की हे मनाचे मांडे आहेत, पण तिने त्यांना हार मानू दिली नाही. आता ते रोज सकाळी वीणेचा सराव करतात आणि मार्चमधल्या त्यांच्या पहिल्या छोट्या मैफलीची आतुरतेने वाट पाहतायत. 'भूतकाळ मी बदलू शकत नाही,' ते म्हणतात, 'पण शेवटी मला दुसरी संधी मिळाली याचा मला आनंद आहे.'",
        "opinions|4:1|4|q0": "तरुणपणी व्यंकटेश यांची कोणती संधी हुकली?",
