        "opinions|4:1|5|scenario": "इम्रानने नुकताच त्याचा प्रवेश परीक्षेचा निकाल पाहिला आहे. कलबुर्गीत ग्रंथालयाबाहेर त्याची मैत्रीण कविता त्याला भेटते.",
        "opinions|4:1|5|l0": "इम्रान, तू नाराज दिसतोयस. प्रवेश परीक्षेचा निकाल लागला का?",
        "opinions|4:1|5|l1": "हो. फक्त चार गुणांनी माझा कट-ऑफ हुकला. मी आधीच तयारी सुरू केली असती तर बरं झालं असतं.",
        "opinions|4:1|5|l2": "खूप वाईट वाटलं. पण चार गुण म्हणजे अगदी थोडा फरक आहे. तुला तुझे विषय नक्कीच चांगले येतात.",
        "opinions|4:1|5|l3": "मी ते दोन महिने व्हिडिओ गेम्समध्ये वाया घालवले नसते तर!",
        "opinions|4:1|5|l4": "मागे वळून पाहताना सगळंच स्पष्ट दिसतं. आता ते बदलता येणार नाही, म्हणून सोडून द्यायचा प्रयत्न कर.",
        "opinions|4:1|5|l5": "माहीत आहे, पण माझ्या आई-वडिलांना खूप आशा होती. मी त्यांची निराशा केली असं वाटतं.",
        "opinions|4:1|5|l6": "त्यांच्याशी मोकळेपणाने बोल. पुढच्या वर्षी तू पुन्हा परीक्षा देऊ शकतोस; ही दुसरी संधी आहे.",
        "opinions|4:1|5|l7": "ते खरं आहे. आणि या वेळी मी पहिल्या दिवसापासून नीट वेळापत्रक बनवेन.",
        "opinions|4:1|5|l8": "बघ? आशेचा किरण आत्ताच दिसतोय. मी तुझ्याबद्दल आशावादी आहे.",
        "opinions|4:1|5|l9": "धन्यवाद, कविता. पुढच्या वर्षी स्वतःला सिद्ध करण्याची मी खरंच आतुरतेने वाट पाहतोय.",
        "opinions|4:1|5|q0": "इम्रानचा कट-ऑफ किती गुणांनी हुकला?",
