        "opinions|5:1|1|p0": "जमिनीच्या एका छोट्या तुकड्यावरून दोन भावांमध्ये भांडण झालं.",
        "opinions|5:1|1|p1": "हा सगळा गैरसमज होता; तुला दुखवायचा तिचा कधीच हेतू नव्हता.",
        "opinions|5:1|1|p2": "आठवडाभर अबोला धरल्यानंतर शेवटी दोघा मित्रांचा एका कप चहावर समेट झाला.",
        "opinions|5:1|1|p3": "मनात अढी ठेवून फक्त तुमचंच नुकसान होतं; क्षमा करून पुढे जायचा प्रयत्न करा.",
        "opinions|5:1|1|p4": "आई-बाबांचा वाद झाला की मी कधीच कोणाची बाजू घेत नाही; मी फक्त दोघांसाठी चहा करतो.",
        "opinions|5:1|2|w0": "विश्वासू",
