        "opinions|6:1|4|q1": "नातेवाइकांच्या टिप्पण्यांबद्दल आजी काय म्हणाली?",
        "opinions|6:1|4|q1o0": "त्यांच्यावर पूर्ण विश्वास ठेवू नकोस",
        "opinions|6:1|4|q1o1": "त्या काळजीपूर्वक पाळ",
