        "opinions|6:1|4|q2o3": "शिष्यवृत्तीच्या ऑफरमुळे",
        "opinions|6:1|5|title": "गोंगाट करणारा रूममेट",
        "opinions|6:1|5|scenario": "धारवाडमध्ये पहिल्या वर्षाला शिकणारा दीपक, वसतिगृहातल्या रूममेटबद्दल सल्ला घेण्यासाठी त्याची मोठी चुलतबहीण शालिनी हिला फोन करतो.",
        "opinions|6:1|5|l0": "शालिनीताई, एका गोष्टीबद्दल तुझा सल्ला घेऊ का? दुसऱ्या कोणाशी बोलावं ते कळत नाहीये.",
        "opinions|6:1|5|l1": "हो, नक्की, दीपक. काय चाललंय मनात?",
        "opinions|6:1|5|l2": "माझा वसतिगृहातला रूममेट रात्री दोन वाजेपर्यंत मोठ्याने गाणी लावतो, आणि मला झोप लागत नाही.",
        "opinions|6:1|5|l3": "हे खरंच थकवणारं आहे. त्याचा तुला काय त्रास होतो, हे तू त्याला सांगितलं आहेस का?",
        "opinions|6:1|5|l4": "तसं नाही. आमचं भांडण होईल अशी मला भीती वाटते, आणि आम्हाला वर्षभर एकत्र राहायचं आहे.",
        "opinions|6:1|5|l5": "मी तुझ्या जागी असते तर, तुम्ही दोघं निवांत असताना त्याच्याशी शांतपणे बोलले असते.",
        "opinions|6:1|5|l6": "ही चांगली सूचना आहे. पण नेमकं काय बोलू?",
        "opinions|6:1|5|l7": "अनुभवाचा एक चांगला नियम म्हणजे त्याच्या चुकांबद्दल नाही, तर तुझ्या अडचणीबद्दल बोल. अकरानंतर हेडफोन वापरायचं तू त्याला का सुचवत नाहीस?",
        "opinions|6:1|5|l8": "हे योग्य वाटतं. मी नीट विचार करतो आणि या वीकेंडला त्याच्याशी बोलतो.",
        "opinions|6:1|5|l9": "छान. आणि फार वाट न पाहिलेलीच बरी, नाहीतर परीक्षेतच झोपशील!",
        "opinions|6:1|5|q0": "दीपकची अडचण काय आहे?",
        "opinions|6:1|5|q0o0": "त्याचा रूममेट रात्री उशिरा मोठ्याने गाणी लावतो",
        "opinions|6:1|5|q0o1": "त्याचा रूममेट खोली कधीच साफ करत नाही",
        "opinions|6:1|5|q0o2": "त्याचा रूममेट त्याच्याकडून पैसे उसने घेतो",
        "opinions|6:1|5|q0o3": "त्याचा रूममेट खूप लवकर उठतो",
        "opinions|6:1|5|q1": "दीपक अजून त्याच्या रूममेटशी का बोलला नाही?",
        "opinions|6:1|5|q1o0": "त्यांचं भांडण होईल अशी त्याला भीती वाटते",
