        "services|1:1|0|w3": "सिरप",
        "services|1:1|0|w4": "औषधाचा डोस",
        "services|1:1|0|w5": "दुष्परिणाम",
        "services|1:1|1|p0": "जवळपास रात्रभर उघडं असणारं एखादं औषधांचं दुकान आहे का?",
        "services|1:1|1|p1": "दहा वर्षांच्या मुलासाठी योग्य डोस किती, ते सांगाल का?",
        "services|1:1|1|p2": "केमिस्टने सांगितलं की प्रत्येक जेवणानंतर एक गोळी घ्यायची.",
        "services|1:1|1|p3": "या खोकल्याच्या सिरपचे झोप येण्यासारखे काही दुष्परिणाम आहेत का?",
        "services|1:1|1|p4": "माफ करा, डॉक्टरांच्या चिठ्ठीशिवाय आम्ही तुम्हाला या गोळ्या देऊ शकत नाही.",
        "services|1:1|2|w0": "मलम",
        "services|1:1|2|w1": "ॲलर्जी",
        "services|1:1|2|w2": "एक्सपायरी तारीख",
        "services|1:1|2|w3": "वेदनाशामक गोळी",
        "services|1:1|2|w4": "अँटिबायोटिक",
        "services|1:1|2|w5": "गुंगी आलेला",
        "services|1:1|3|p0": "हे मलम भाजलेल्या जागी दिवसातून दोनदा हलक्या हाताने लावा.",
        "services|1:1|3|p1": "मला पेनिसिलिनची ॲलर्जी आहे, म्हणून कृपया दुसरं काहीतरी सुचवा.",
        "services|1:1|3|p2": "नवी स्ट्रिप उघडण्याआधी नेहमी एक्सपायरी तारीख तपासा.",
        "services|1:1|3|p3": "बरं वाटलं तरी अँटिबायोटिकचा पूर्ण कोर्स संपवा.",
        "services|1:1|3|p4": "या वेदनाशामक गोळीने गुंगी येऊ शकते, म्हणून ती घेतल्यावर गाडी चालवू नका.",
        "services|1:1|4|title": "रात्री उशिरा औषधांच्या दुकानात",
        "services|1:1|4|text": "म्हैसूरमध्ये एका रात्री दहा वाजता मीराचा धाकटा भाऊ रोहन खूप ताप येऊन जागा झाला. त्यांच्या फॅमिली डॉक्टर गावाबाहेर गेल्या होत्या, म्हणून मीराने त्यांना फोन करून सल्ला विचारला. डॉक्टर म्हणाल्या की सकाळपर्यंत तापाचं सिरप पुरेसं आहे. मीराला बसस्टँडजवळ रात्रभर उघडं असणारं एक औषधांचं दुकान सापडलं. तिने केमिस्टला सांगितलं की रोहन आठ वर्षांचा आहे आणि त्याला एका अँटिबायोटिकची ॲलर्जी आहे. केमिस्टने एक्सपायरी तारीख तपासली, डब्यावर डोस लिहून दिला आणि सांगितलं की सिरपमुळे रोहनला गुंगी येऊ शकते. सकाळपर्यंत रोहनचा ताप उतरला होता आणि तो डोसा मागत होता.",
        "services|1:1|4|q0": "मीरा रात्री औषधांच्या दुकानात का गेली?",
        "services|1:1|4|q0o0": "रोहनला खूप ताप आला होता",
        "services|1:1|4|q0o1": "तिला फोनचा नवा चार्जर हवा होता",
