        "services|1:1|5|title": "केमिस्टचा सल्ला",
        "services|1:1|5|scenario": "किरणला जोरदार सर्दी झाली आहे, आणि तो हुबळीतल्या केमिस्ट लताकडे सल्ला मागतो.",
        "services|1:1|5|l0": "नमस्कार. मी तुमची काय मदत करू?",
        "services|1:1|5|l1": "नमस्कार. कालपासून माझं नाक बंद आहे आणि घसा दुखतोय. काहीतरी सुचवाल का?",
        "services|1:1|5|l2": "तुम्हाला ताप आहे का, किंवा कोणत्या औषधाची ॲलर्जी आहे का?",
        "services|1:1|5|l3": "ताप नाही, आणि माझ्या माहितीप्रमाणे कसलीच ॲलर्जी नाही. फार जहाल काही घ्यायला नको वाटतं.",
        "services|1:1|5|l4": "मग सर्दीसाठी या गोळ्या घ्या, एक सकाळी आणि एक रात्री, जेवणानंतर.",
        "services|1:1|5|l5": "मला माहीत असायला हवेत असे काही दुष्परिणाम आहेत का?",
        "services|1:1|5|l6": "यांनी थोडी गुंगी येऊ शकते, म्हणून रात्रीची गोळी घेतल्यावर गाडी चालवू नका.",
        "services|1:1|5|l7": "समजलं. आणि घशासाठीही काही आहे का?",
        "services|1:1|5|l8": "हे सिरप उपयोगी पडेल: दोन चमचे, दिवसातून तीनदा. तीन दिवसांत बरं वाटलं नाही, तर कृपया डॉक्टरांना दाखवा.",
        "services|1:1|5|l9": "फार उपयोगी माहिती, धन्यवाद. मी यूपीआयने पैसे देऊ शकतो का?",
        "services|1:1|5|q0": "किरणने गोळ्या किती वेळा घ्यायच्या आहेत?",
        "services|1:1|5|q0o0": "दिवसातून दोनदा, जेवणानंतर",
