        "services|2:1|0|w5": "खूण",
        "services|2:1|1|p0": "मला हुबळी बसस्टँडजवळ झालेल्या रस्ते अपघाताची माहिती द्यायची आहे.",
        "services|2:1|1|p1": "कृपया लवकर रुग्णवाहिका पाठवा; एक माणूस रस्त्यावर पडलेला आहे.",
        "services|2:1|1|p2": "आपत्कालीन परिस्थितीत 112 हेल्पलाइनला फोन करा आणि सावकाश व स्पष्ट बोला.",
        "services|2:1|1|p3": "अग्निशमन दल येतंय, त्यामुळे कृपया आत्ताच इमारतीबाहेर पडा.",
        "services|2:1|1|p4": "सगळ्यात जवळची खूण म्हणजे पेट्रोल पंपासमोरचं मोठं मंदिर.",
        "services|2:1|2|w0": "जखमी",
