        "services|2:1|2|w5": "घाबरगुंडी",
        "services|2:1|3|p0": "दोन माणसं जखमी आहेत, आणि त्यांपैकी एक बेशुद्ध आहे.",
        "services|2:1|3|p1": "रक्त थांबवण्यासाठी जखमेवर स्वच्छ कापड दाबून धरा.",
        "services|2:1|3|p2": "तुम्हाला प्रथमोपचार येतात का, की आपण रुग्णवाहिकेची वाट पाहायची?",
        "services|2:1|3|p3": "स्टेशनवर माझी बॅग चोरीला गेली, आणि मला चोरीची तक्रार नोंदवायची आहे.",
        "services|2:1|3|p4": "घाबरू नका; दीर्घ श्वास घ्या आणि मला तुमचा पत्ता सांगा.",
        "services|2:1|4|title": "महामार्गावरची मदत",
        "services|2:1|4|text": "रवी मंगळुरूहून उडुपीला गाडी चालवत चालला होता, तेव्हा त्याला महामार्गाच्या कडेला एक बाईक पडलेली दिसली. तिच्याजवळ एक तरुण बसला होता, आणि त्याच्या हातातून खूप रक्त वाहत होतं. रवीने गाडी थांबवली आणि स्वतःला बजावलं की घाबरायचं नाही. त्याने 108 ला फोन केला आणि म्हणाला, 'मला एका अपघाताची माहिती द्यायची आहे; एक माणूस जखमी आहे.' ऑपरेटरने नेमकं ठिकाण विचारलं, म्हणून रवीने सगळ्यात जवळची खूण सांगितली, सुरथकलचं दीपगृह. वाट पाहत असताना रवीने जखमेवर स्वच्छ टॉवेल दाबून प्रथमोपचार केले. पंधरा मिनिटांत रुग्णवाहिका आली, आणि नंतर त्या तरुणाने शांत राहिल्याबद्दल रवीचे आभार मानले.",
        "services|2:1|4|q0": "रवीला बाईक कुठे दिसली?",
