        "services|2:1|5|title": "112 ला फोन",
        "services|2:1|5|scenario": "नंदिनीला पुण्यात तिच्या गल्लीतल्या एका घरातून धूर येताना दिसतो, आणि ती 112 आपत्कालीन हेल्पलाइनला फोन करते. सुरेश फोन उचलतो.",
        "services|2:1|5|l0": "112 आपत्कालीन हेल्पलाइन. काय आपत्कालीन परिस्थिती आहे?",
        "services|2:1|5|l1": "माझ्या गल्लीतल्या एका घराला आग लागली आहे. वरच्या खिडकीतून दाट धूर येताना दिसतोय.",
        "services|2:1|5|l2": "कृपया शांत राहा, मॅडम. घरात अजून कोणी आहे का?",
        "services|2:1|5|l3": "मला खात्री नाही. तिथे एक म्हातारं जोडपं राहतं, आणि ते बाहेर दिसत नाहीयेत.",
        "services|2:1|5|l4": "मी आत्ताच अग्निशमन दल आणि रुग्णवाहिका पाठवतो. नेमका पत्ता काय आहे?",
        "services|2:1|5|l5": "घर नंबर 14, शांती नगर, कोथरूड. कोपऱ्यावरची निळी पाण्याची टाकी ही खूण आहे.",
        "services|2:1|5|l6": "धन्यवाद. कृपया आत जाऊ नका, आणि इतर लोकांना धुरापासून दूर ठेवा.",
        "services|2:1|5|l7": "ठीक आहे. अरे, एक शेजारी सांगतायत की ते जोडपं मंदिरात गेलंय, म्हणजे घर रिकामं आहे.",
        "services|2:1|5|l8": "ही चांगली बातमी आहे. अग्निशमन दल साधारण दहा मिनिटांत तुमच्यापर्यंत पोहोचेल. कृपया फोन चालू ठेवा.",
        "services|2:1|5|l9": "खूप खूप धन्यवाद. मला आत्ताच सायरन ऐकू येतोय.",
