        "services|3:1|0|w5": "फ्यूज",
        "services|3:1|1|p0": "स्वयंपाकघरातला नळ रात्रभर टपकतोय; आज प्लंबर पाठवू शकाल का?",
        "services|3:1|1|p1": "बाथरूमच्या सिंकखाली गळती आहे, आणि जमीन नेहमी ओली असते.",
        "services|3:1|1|p2": "मी गिझर सुरू केला की दर वेळी फ्यूज उडतो.",
        "services|3:1|1|p3": "इलेक्ट्रिशियन म्हणतो की या फ्लॅटमधलं जुनं वायरिंग सुरक्षित नाही.",
        "services|3:1|1|p4": "कुठल्याही वायरला हात लावण्याआधी कृपया मेन स्विच बंद करा.",
