        "services|3:1|2|w5": "सर्व्हिस चार्ज",
        "services|3:1|3|p0": "आमच्या वॉशिंग मशीनमध्ये बिघाड आहे; दर वेळी धुताना ते मध्येच बंद पडतं.",
        "services|3:1|3|p1": "मी कामाला निघण्याआधी, उद्या सकाळी तंत्रज्ञ येऊ शकेल का?",
        "services|3:1|3|p2": "काम सुरू करण्याआधी एकूण खर्चाचा अंदाज सांगू शकाल का?",
        "services|3:1|3|p3": "सुटा भाग बंगळुरूहून यायला तीन दिवस लागतील.",
        "services|3:1|3|p4": "कोणत्याही मोठ्या उपकरणासाठी सर्व्हिस चार्ज दर भेटीला तीनशे रुपये आहे.",
        "services|3:1|4|title": "थंड न करणारा फ्रीज",
        "services|3:1|4|text": "मे महिन्यातल्या कलबुर्गीच्या एका कडक उन्हाळी आठवड्यात कुलकर्णी कुटुंबाचा फ्रीज अचानक थंड करायचा बंद झाला. सुनीताने कंपनीच्या सर्व्हिस सेंटरला फोन केला आणि बिघाड नीट समजावून सांगितला: दिवा लागत होता, पण आतून फ्रीज गरम होता. दुसऱ्या दिवशी दुपारी एक तंत्रज्ञ आला आणि त्याने उपकरण नीट तपासलं. त्याने सांगितलं की थंड करणाऱ्या यंत्रणेतला एक सुटा भाग खराब झाला आहे आणि तो बदलावा लागेल. काम सुरू होण्याआधी सुनीताने नम्रपणे खर्चाचा अंदाज विचारला, आणि त्याने सांगितलं की सर्व्हिस चार्ज धरून एकूण साधारण दोन हजार रुपये होतील. दोन दिवसांनी हुबळीहून तो भाग आला, आणि तंत्रज्ञाने तासाभरात फ्रीज दुरुस्त केला. त्या संध्याकाळी फ्रीज पुन्हा थंड झाला, आणि कुटुंबाला शेवटी दूध-दही ठेवता आलं.",
        "services|3:1|4|q0": "फ्रीजमध्ये काय बिघाड होता?",
        "services|3:1|4|q0o0": "तो थंड करायचा बंद झाला होता",
