        "services|3:1|5|title": "इलेक्ट्रिशियनला बोलावणं",
        "services|3:1|5|scenario": "फरहानच्या फ्लॅटमधला फ्यूज सारखा उडतोय, म्हणून तो म्हैसूरमध्ये घरदुरुस्ती सेवा चालवणाऱ्या आशाला फोन करतो.",
        "services|3:1|5|l0": "नमस्कार, क्विकफिक्स होम सर्व्हिसेस. मी आशा बोलतेय. मी काय मदत करू?",
        "services|3:1|5|l1": "नमस्कार, मी विजेच्या एका अडचणीबद्दल फोन केलाय. माझ्या फ्लॅटमधला फ्यूज सारखा उडतो, बहुतेक संध्याकाळी.",
        "services|3:1|5|l2": "अच्छा. एखादं ठराविक उपकरण सुरू केल्यावर असं होतं का?",
        "services|3:1|5|l3": "मला वाटतं हो. गिझर आणि इस्त्री एकत्र चालू असताना बहुतेक वेळा असं होतं.",
        "services|3:1|5|l4": "वायरिंगमध्ये बिघाड असू शकतो. मी तपासायला इलेक्ट्रिशियन पाठवू शकते. तुम्हाला कधी सोयीचं आहे?",
        "services|3:1|5|l5": "आजच कोणाला पाठवू शकाल का? मी सहा वाजेपर्यंत घरून काम करतोय.",
        "services|3:1|5|l6": "आमचा इलेक्ट्रिशियन महेश चार वाजता येऊ शकेल. भेटीचा सर्व्हिस चार्ज अडीचशे रुपये आहे.",
        "services|3:1|5|l7": "चालेल. दुरुस्ती सुरू करण्याआधी तो मला खर्चाचा अंदाज देईल ना?",
        "services|3:1|5|l8": "हो, तो नेहमी आधी खर्च समजावून सांगतो. कृपया तुमचा पत्ता व्हॉट्सॲपवर पाठवा.",
        "services|3:1|5|l9": "छान, मी लगेच पाठवतो. धन्यवाद.",
