        "services|4:1|1|p0": "गेल्या आठवड्यात इथून घेतलेल्या मिक्सरबद्दल मला तक्रार करायची आहे.",
        "services|4:1|1|p1": "मोटर सदोष आहे, त्यामुळे मला बदलून दुसरा मिक्सर किंवा पूर्ण पैसे परत हवे आहेत.",
        "services|4:1|1|p2": "ही घ्या पावती, आणि डब्यात अजूनही सगळे भाग आहेत.",
        "services|4:1|1|p3": "तो अजून वॉरंटीत आहे, त्यामुळे दुरुस्ती मोफत व्हायला हवी.",
        "services|4:1|1|p4": "माफ करा, पण व्हाउचर पुरेसं नाही; मला खरंच पैसे परत हवे आहेत.",
        "services|4:1|2|w0": "ग्राहक सेवा",
        "services|4:1|2|w1": "सुपरवायझर",
        "services|4:1|2|w2": "वरिष्ठांकडे नेणे",
        "services|4:1|2|w3": "नुकसानभरपाई",
        "services|4:1|2|w4": "डिलिव्हरी",
        "services|4:1|2|w5": "गैरसोय",
        "services|4:1|3|p0": "मी ग्राहक सेवेला तीनदा फोन केला, पण कोणीही अडचण सोडवली नाही.",
        "services|4:1|3|p1": "मी याबद्दल तुमच्या सुपरवायझरशी बोलू शकतो का?",
        "services|4:1|3|p2": "शुक्रवारपर्यंत हे दुरुस्त झालं नाही, तर मला माझी तक्रार वरिष्ठांकडे न्यावी लागेल.",
        "services|4:1|3|p3": "डिलिव्हरी दहा दिवस उशिरा झाली, आणि पार्सल खराब झालं होतं.",
        "services|4:1|3|p4": "झालेल्या गैरसोयीबद्दल आम्ही माफी मागतो आणि नुकसानभरपाई म्हणून दोनशे रुपये जमा करू.",
        "services|4:1|4|title": "नम्र, पण ठाम",
        "services|4:1|4|text": "इम्रानने बेळगावमधल्या आईसाठी ऑनलाइन एक इलेक्ट्रिक केटल मागवली, पण डिलिव्हरी एक आठवडा उशिरा आली. आईने ती सुरू केल्यावर केटलमधून जळका वास आला आणि ती बंद पडली. इम्रानने ग्राहक सेवेला फोन केला, ऑर्डर नंबर दिला आणि वस्तू सदोष असल्याचं सांगितलं. पहिल्या एजंटने फक्त व्हाउचर देऊ केलं, म्हणून इम्रानने नम्रपणे सुपरवायझरशी बोलायची विनंती केली. तो शांत पण ठाम राहिला आणि म्हणाला, 'माफ करा, पण व्हाउचर पुरेसं नाही; केटल वॉरंटीत आहे, आणि माझ्याकडे पावती आहे.' सुपरवायझरने गैरसोयीबद्दल माफी मागितली आणि दोन दिवसांत बदली केटल पाठवायचं मान्य केलं. उशिरा झालेल्या डिलिव्हरीची नुकसानभरपाई म्हणून तिने त्याच्या खात्यात शंभर रुपयेही जमा केले.",
        "services|4:1|4|q0": "केटलमध्ये काय बिघाड होता?",
        "services|4:1|4|q0o0": "तिच्यातून जळका वास आला आणि ती बंद पडली",
