        "services|4:1|4|q2o2": "पुढच्या महिन्यात केटल दुरुस्त करायची",
        "services|4:1|4|q2o3": "त्याच्या घरी तंत्रज्ञ पाठवायचा",
        "services|4:1|5|title": "ग्राहक सेवेला फोन",
        "services|4:1|5|scenario": "दीपाला चुकीचा कुर्ता मिळाला, म्हणून ती एका ऑनलाइन दुकानाच्या ग्राहक सेवा लाइनला फोन करते. प्रकाश फोन उचलतो.",
        "services|4:1|5|l0": "शॉपकार्ट ग्राहक सेवेला फोन केल्याबद्दल धन्यवाद. मी प्रकाश बोलतोय. मी तुमची काय मदत करू?",
        "services|4:1|5|l1": "नमस्कार प्रकाश. मी ऑर्डर नंबर 4582 बद्दल फोन केलाय. मला काल चुकीची वस्तू मिळाली.",
        "services|4:1|5|l2": "हे ऐकून वाईट वाटलं. तुम्ही काय मागवलं होतं आणि तुम्हाला काय मिळालं, ते सांगाल का?",
        "services|4:1|5|l3": "मी मीडियम साइझमधला निळा सुती कुर्ता मागवला होता, पण मला एक्स्ट्रा लार्जमधला लाल कुर्ता मिळाला.",
        "services|4:1|5|l4": "झालेल्या गैरसोयीबद्दल माफी मागतो. तुम्हाला बदलून दुसरा हवा आहे की पैसे परत?",
        "services|4:1|5|l5": "मला पैसे परत हवे आहेत, प्लीज. मला तो या रविवारी लग्नासाठी हवा होता, आणि नवा कुर्ता वेळेवर येणार नाही.",
        "services|4:1|5|l6": "समजलं. आमचा डिलिव्हरी पार्टनर उद्या दहा ते दोनच्या दरम्यान पार्सल घेऊन जाईल.",
        "services|4:1|5|l7": "आणि पैसे माझ्या खात्यात यायला किती वेळ लागेल?",
        "services|4:1|5|l8": "पार्सल घेऊन गेल्यावर पाच कामकाजाच्या दिवसांत पैसे तुमच्या खात्यात जमा होतील.",
        "services|4:1|5|l9": "ठीक आहे. मला तक्रार नंबरही एसएमएसने पाठवाल का?",
