        "services|5:1|1|p0": "उत्पन्नाच्या दाखल्याचा अर्ज मला कुठे मिळेल?",
        "services|5:1|1|p1": "कृपया मूळ कागदपत्रं आणि प्रत्येकाची एक झेरॉक्स प्रत घेऊन या.",
        "services|5:1|1|p2": "तुम्ही दुसऱ्या पानावर सही करायला विसरलात.",
