        "services|5:1|3|p0": "कृपया टोकन घ्या आणि तुमचा नंबर पुकारला जाईपर्यंत थांबा.",
        "services|5:1|3|p1": "ऐका ना, आधार अपडेटसाठी हीच रांग आहे का?",
        "services|5:1|3|p2": "अधिकाऱ्यांनी सांगितलं की माझ्या बोटांचे ठसे पुन्हा स्कॅन करावे लागतील.",
        "services|5:1|3|p3": "पासपोर्टसाठी पोलीस पडताळणीला साधारणपणे दोन आठवडे लागतात.",
        "services|5:1|3|p4": "ही पोचपावती जपून ठेवा; अर्जाची स्थिती पाहण्यासाठी ती लागेल.",
        "services|5:1|4|title": "आधार केंद्रावरची एक सकाळ",
        "services|5:1|4|text": "लक्ष्मी कामासाठी शिवमोग्गाहून पुण्याला आली होती, त्यामुळे तिला आधार कार्डवरचा पत्ता बदलायचा होता. ती सकाळी आठ वाजता आधार केंद्रावर पोहोचली, पण तोपर्यंत रांग लांब झाली होती. एका रखवालदाराने तिला बेचाळीस नंबरचं टोकन आणि भरायला एक अर्ज दिला. तिचा नंबर आल्यावर अधिकाऱ्यांनी तिची कागदपत्रं तपासली आणि पत्त्याचा पुरावा म्हणून वीज बिलाची झेरॉक्स मागितली. सुदैवाने लक्ष्मीने दोन प्रती आणल्या होत्या, आणि प्रत्येक पानावर आधीच सही केली होती. मग अधिकाऱ्यांनी पडताळणीसाठी तिच्या बोटांचे ठसे स्कॅन केले आणि पोचपावती छापून दिली. त्यांनी सांगितलं की दहा दिवसांत नवा पत्ता अपडेट होईल, आणि लक्ष्मी हुश्श करत दुपारच्या आधीच ऑफिसमधून बाहेर पडली.",
        "services|5:1|4|q0": "लक्ष्मी आधार केंद्रावर का गेली?",
