        "services|5:1|5|scenario": "विक्रम हुबळीच्या पासपोर्ट सेवा केंद्रात आहे, जिथे काउंटरवरच्या अधिकारी शालिनी त्याची कागदपत्रं तपासतात.",
        "services|5:1|5|l0": "नमस्कार. तुमची टोकन स्लिप आणि अपॉइंटमेंटची प्रिंट द्याल का?",
        "services|5:1|5|l1": "नमस्कार मॅडम. ही घ्या. हा माझा पहिलाच पासपोर्ट अर्ज आहे.",
        "services|5:1|5|l2": "धन्यवाद. मला तुमचं आधार कार्ड आणि पत्त्याचा आणखी एक पुरावा हवा आहे. तुम्ही काय आणलं आहे?",
        "services|5:1|5|l3": "माझ्याकडे आधार कार्ड, जन्मतारखेसाठी दहावीचं प्रमाणपत्र आणि अलीकडचं गॅस बिल आहे.",
        "services|5:1|5|l4": "गॅस बिल तुमच्या वडिलांच्या नावावर आहे. तुमच्या स्वतःच्या नावावर काही आहे का?",
        "services|5:1|5|l5": "तसं काही नाही, पण माझ्या पत्त्यासह बँक पासबुकची झेरॉक्स आणली आहे. ती चालेल का?",
        "services|5:1|5|l6": "हो, ते चालेल. कृपया इथे सही करा, आणि मग फोटो आणि बोटांच्या ठशांसाठी बी काउंटरवर जा.",
        "services|5:1|5|l7": "नक्की. यानंतर पोलीस पडताळणीला किती वेळ लागेल?",
        "services|5:1|5|l8": "साधारणपणे दोन ते तीन आठवडे. पोलीस तुमच्याकडे यायला तयार झाले की तुम्हाला एसएमएस येईल.",
        "services|5:1|5|l9": "तुमच्या मदतीबद्दल खूप खूप धन्यवाद, मॅडम.",
