        "services|6:1|1|p0": "बंगळुरूचे घरमालक अनेकदा अनामत रक्कम म्हणून दहा महिन्यांचं भाडं मागतात.",
        "services|6:1|1|p1": "भाड्यात काही कमी-जास्त होऊ शकतं का, की हीच अंतिम रक्कम आहे?",
        "services|6:1|1|p2": "दलाल त्याची फी म्हणून एका महिन्याचं भाडं घेतो.",
        "services|6:1|1|p3": "आम्ही मेट्रो स्टेशनजवळ पूर्ण सुसज्ज फ्लॅट शोधतोय.",
        "services|6:1|1|p4": "भाडेकरू म्हणून प्रत्येक पेमेंटची पावती मिळणं हा तुमचा हक्क आहे.",
        "services|6:1|2|w0": "भाडेकरार",
        "services|6:1|2|w1": "देखभाल खर्च",
        "services|6:1|2|w2": "शेजारी",
        "services|6:1|2|w3": "नोटीस कालावधी",
        "services|6:1|2|w4": "घर खाली करणे",
        "services|6:1|2|w5": "वीज मीटर",
        "services|6:1|3|p0": "भाडेकरारावर सही करण्याआधी तो कृपया नीट वाचा.",
        "services|6:1|3|p1": "महिन्याचा देखभाल खर्च भाड्यात धरलेला आहे, की तो वेगळा द्यायचा?",
        "services|6:1|3|p2": "आमचे शेजारी मनमिळाऊ आहेत, पण ते रात्री उशिरा मोठ्या आवाजात गाणी लावतात.",
        "services|6:1|3|p3": "नोटीस कालावधी दोन महिने आहे, त्यामुळे आपल्याला जुलैपर्यंत घरमालकांना सांगायला हवं.",
        "services|6:1|3|p4": "फ्लॅट खाली करताना आपण वीज मीटरचं रीडिंग लिहून ठेवू.",
        "services|6:1|4|title": "म्हैसूरमधला नवा फ्लॅट",
        "services|6:1|4|text": "म्हैसूरमध्ये नोकरी लागल्यावर अनिता कुवेंपुनगरजवळ एक छोटा फ्लॅट शोधू लागली. एका दलालाने तिला चार जागा दाखवल्या, आणि तिला दुसऱ्या मजल्यावरचा एक सुसज्ज वन-बेडरूम फ्लॅट आवडला. घरमालक श्री. गौडा यांनी महिना बारा हजार रुपये भाडं आणि साठ हजार अनामत रक्कम मागितली. अनिताने नम्रपणे विचारलं की अनामत रक्कम थोडी कमी होऊ शकेल का, आणि शेवटी पन्नास हजारावर दोघांचं एकमत झालं. भाडेकरारावर सही करण्याआधी तिने नोटीस कालावधी तपासला आणि महिन्याचा देखभाल खर्च कोण भरणार, हे विचारलं. नंतर बिलांबद्दल गोंधळ होऊ नये म्हणून तिने वीज मीटरचा फोटोही काढून ठेवला. पहिल्याच संध्याकाळी एका मनमिळाऊ शेजारणीने तिच्यासाठी गरम बिसी बेळे भाताची प्लेट आणली.",
        "services|6:1|4|q0": "शेवटी अनिताने किती अनामत रक्कम द्यायचं मान्य केलं?",
        "services|6:1|4|q0o0": "पन्नास हजार रुपये",
