        "services|6:1|5|title": "घरमालकीणबाईंना फोन",
        "services|6:1|5|scenario": "पुण्यात भाड्याने राहणारा राहुल फ्लॅटमधल्या एका अडचणीबद्दल आणि घर सोडण्याबद्दल त्याच्या घरमालकीण श्रीमती जोशी यांना फोन करतो.",
        "services|6:1|5|l0": "नमस्कार जोशी काकू. मी 3बी फ्लॅटमधला राहुल बोलतोय. तुमच्याकडे एक मिनिट आहे का?",
        "services|6:1|5|l1": "हो राहुल, बोल. सगळं ठीक आहे ना?",
        "services|6:1|5|l2": "तसं नाही. सोमवारपासून बाथरूमच्या छतातून पाणी गळतंय, आणि भिंत ओलसर होतेय.",
        "services|6:1|5|l3": "अरे बापरे. ती गच्चीवरची टाकी असणार. मी उद्या सकाळी आमच्या प्लंबरला, सुनीलला पाठवते.",
        "services|6:1|5|l4": "धन्यवाद. दुरुस्तीचा खर्च देखभाल खर्चातून जाईल, की तो मी भरायचा?",
        "services|6:1|5|l5": "काळजी करू नकोस, घरमालकीण म्हणून ती माझी जबाबदारी आहे. तू फक्त बल्बसारख्या छोट्या गोष्टींचे पैसे भरायचे.",
        "services|6:1|5|l6": "तुम्ही फार चांगल्या आहात. अजून एक गोष्ट: माझी कंपनी मला मार्चमध्ये नाशिकला पाठवतेय.",
        "services|6:1|5|l7": "अच्छा. करारानुसार नोटीस कालावधी दोन महिने आहे, त्यामुळे जानेवारीपर्यंत मला लेखी नोटीस दे.",
        "services|6:1|5|l8": "मी याच आठवड्यात तुम्हाला ईमेलने नोटीस पाठवतो. आणि घर खाली केल्यावर अनामत रक्कम परत मिळेल ना?",
        "services|6:1|5|l9": "हो. फ्लॅट आणि शेवटचं वीज बिल तपासल्यावर मी आठवड्याभरात ती ट्रान्सफर करेन.",
        "services|6:1|5|q0": "राहुल कोणती अडचण सांगतो?",
