        "workplace|1:1|1|p0": "माझ्या सध्याच्या भूमिकेत मी संपूर्ण कंपनीचे पगार सांभाळतो.",
        "workplace|1:1|1|p1": "तुम्ही कोणत्या विभागात काम करता, आणि तुमचे वरिष्ठ कोण आहेत?",
        "workplace|1:1|1|p2": "कागदोपत्री माझं पद सीनियर ॲनालिस्ट आहे, पण माझी कामं दर आठवड्याला बदलतात.",
        "workplace|1:1|1|p3": "मी सहा जणांच्या टीमवर देखरेख करतो आणि क्लायंटचे बहुतेक कॉल सांभाळतो.",
        "workplace|1:1|1|p4": "नेहमीच्या दिवशी मी जेवणाआधी तातडीची कामं संपवतो आणि उरलेल्या कामांचं नियोजन करतो.",
