        "workplace|1:1|2|w5": "खासियत असणे",
        "workplace|1:1|3|p0": "आमचं मुख्यालय बंगळुरूमध्ये आहे, पण आमचं बहुतेक मनुष्यबळ हुबळीत आहे.",
        "workplace|1:1|3|p1": "आम्ही दवाखान्यांसाठी बिलिंग सॉफ्टवेअर बनवणारं एक छोटं स्टार्टअप आहोत.",
        "workplace|1:1|3|p2": "म्हैसूरजवळचा आमचा कारखाना भारतातल्या बहुतेक दुचाकी ब्रँडसाठी ब्रेकचे भाग बनवतो.",
        "workplace|1:1|3|p3": "ग्रामीण आरोग्यसेवेतलं आमचं प्रावीण्य हेच आम्हाला वेगळं बनवतं.",
        "workplace|1:1|3|p4": "लहान शहरांतल्या दुकानांना ऑनलाइन विक्री सुरू करायला मदत करणं ही आमची खासियत आहे.",
        "workplace|1:1|4|title": "तू नेमकं काय काम करतोस?",
        "workplace|1:1|4|text": "धारवाडमध्ये घरच्या एका लग्नात निखिलच्या काकांनी त्याला विचारलं की तो कामावर नेमकं काय करतो. निखिलने सांगितलं की तो शेतकऱ्यांसाठी मातीचे सेन्सर बनवणाऱ्या एका स्टार्टअपमध्ये काम करतो. कंपनीचं मुख्यालय बंगळुरूमध्ये आहे, पण सेन्सरचं उत्पादन हुबळीजवळच्या एका छोट्या कारखान्यात होतं. त्याचं पद प्रॉडक्ट इंजिनिअर आहे, आणि तो टेस्टिंग विभागात आहे. प्रत्येक नवा सेन्सर शेतकऱ्यांकडे जाण्याआधी तपासणं हे त्याचं मुख्य काम आहे. तो दोन ज्युनियर इंजिनिअरच्या कामावर देखरेखही करतो आणि कारखान्यातल्या टीमचे प्रश्न सांभाळतो. काका हसले आणि म्हणाले की कंपनीचं मनुष्यबळ खूप मोठं असणार. निखिल हसून म्हणाला की तिथे फक्त चाळीस लोक आहेत, पण त्यातल्या प्रत्येकाकडे खरं प्रावीण्य आहे.",
        "workplace|1:1|4|q0": "निखिलची कंपनी काय बनवते?",
