        "workplace|1:1|5|title": "मग, तुम्ही काय करता?",
        "workplace|1:1|5|scenario": "बंगळुरूमधल्या एका व्यावसायिक कार्यक्रमात अनन्या आणि फरहान पहिल्यांदाच भेटतात आणि आपापल्या नोकरीबद्दल बोलतात.",
        "workplace|1:1|5|l0": "नमस्कार, मी सह्याद्री लॉजिस्टिक्सचा फरहान. तुम्ही या कार्यक्रमाला कशा काय आलात?",
        "workplace|1:1|5|l1": "तुम्हाला भेटून आनंद झाला. मी अनन्या. मी एका फिनटेक स्टार्टअपमध्ये ग्राहक सहाय्य टीमची प्रमुख आहे.",
        "workplace|1:1|5|l2": "छान. तुमची कंपनी नेमकं काय करते?",
        "workplace|1:1|5|l3": "आम्ही एक ॲप बनवलं आहे, जे छोट्या दुकानदारांना हिशोब ठेवायला आणि डिजिटल पेमेंट घ्यायला मदत करतं.",
        "workplace|1:1|5|l4": "आणि तुमचा नेहमीचा दिवस कसा असतो?",
        "workplace|1:1|5|l5": "मी माझ्या टीमसोबत एका छोट्या कॉलने सुरुवात करते, आणि मग अवघड तक्रारी मी स्वतः सांभाळते.",
        "workplace|1:1|5|l6": "खूप जबाबदारीचं काम दिसतंय. तुमची टीम किती मोठी आहे?",
        "workplace|1:1|5|l7": "दोन शिफ्टमध्ये मिळून बारा लोक. आणि तुमचं काय? तुमची भूमिका काय आहे?",
        "workplace|1:1|5|l8": "मी रूट प्लॅनर आहे. थोडक्यात, आमचे ट्रक सगळ्यात जलद आणि स्वस्त रस्त्यांनी जातील, याची मी काळजी घेतो.",
        "workplace|1:1|5|l9": "म्हणजे माझी पार्सलं वेळेवर येतात ती तुमच्यामुळे! आपण संपर्कात राहू या.",
        "workplace|1:1|5|q0": "अनन्याच्या कंपनीने काय बनवलं आहे?",
        "workplace|1:1|5|q0o0": "छोट्या दुकानदारांसाठी एक ॲप",
