        "workplace|3:1|0|w5": "आकडा",
        "workplace|3:1|1|p0": "आज आपण कशावर बोलणार आहोत, याच्या थोडक्यात आढाव्याने मी सुरुवात करतो.",
        "workplace|3:1|1|p1": "या स्लाइडवर तुम्ही पाहू शकता की मार्चनंतर विक्री दुप्पट झाली.",
        "workplace|3:1|1|p2": "मी रूपरेषा सोपी ठेवली आहे: समस्या, उपाय, खर्च आणि वेळापत्रक.",
        "workplace|3:1|1|p3": "हा आलेख गेल्या दोन वर्षांचे आमचे महिन्याचे आकडे दाखवतो.",
        "workplace|3:1|1|p4": "मला खास करून एक आकडा अधोरेखित करायचा आहे: आमचा खर्च बारा टक्क्यांनी कमी झाला.",
        "workplace|3:1|2|w0": "प्रोजेक्टर",
