        "workplace|3:1|2|w4": "समारोप करणे",
        "workplace|3:1|2|w5": "सारांश सांगणे",
        "workplace|3:1|3|p0": "कोणी प्रोजेक्टर तपासेल का? स्लाइड्स खूप अंधुक दिसतायत.",
        "workplace|3:1|3|p1": "मी संपूर्ण भाषणाचा दोनदा सराव केला, त्यामुळे त्याला नेमका किती वेळ लागतो हे मला माहीत आहे.",
        "workplace|3:1|3|p2": "सगळे आकडे असलेलं माहितीपत्रक दिलं आहे, त्यामुळे तुम्हाला नोंदी घ्यायची गरज नाही.",
        "workplace|3:1|3|p3": "चांगला प्रश्न आहे; एकूण खर्च म्हणजे मला काय म्हणायचं होतं, ते मी स्पष्ट करतो.",
        "workplace|3:1|3|p4": "समारोप करताना, मी तीन मुख्य मुद्द्यांचा एका मिनिटात सारांश सांगतो.",
        "workplace|3:1|4|title": "रेखाचा महत्त्वाचा दिवस",
        "workplace|3:1|4|text": "हुबळीतल्या मार्केटिंग एक्झिक्युटिव्ह रेखाला कंपनीच्या संचालकांसमोर वार्षिक निकाल सादर करायचे होते. तिने एक सोपी रूपरेषा आणि फक्त आठ स्लाइड्स तयार केल्या, प्रत्येकीवर एक स्पष्ट आलेख. आदल्या रात्री तिने बहिणीसमोर संपूर्ण भाषणाचा तीनदा सराव केला. त्या दिवशी, ती सुरुवात करणार त्याच्या पाच मिनिटं आधी मीटिंग रूममधला प्रोजेक्टर बंद पडला. सुदैवाने रेखाने सगळ्या महत्त्वाच्या आकड्यांची माहितीपत्रकं छापून आणली होती. तिने थोडक्यात आढाव्याने सुरुवात केली आणि मग डिलिव्हरीचा खर्च किती कमी झाला, ते अधोरेखित केलं. एका संचालकांनी बेळगावच्या नव्या दुकानाबद्दल विचारलं, तेव्हा तिने शांतपणे आकडे स्पष्ट केले. तिच्या तीन मुख्य मुद्द्यांचा सारांश सांगून तिने समारोप केला, आणि इतक्या स्पष्टपणे मांडल्याबद्दल संचालकांनी तिचे आभार मानले.",
        "workplace|3:1|4|q0": "रेखाने किती स्लाइड्स तयार केल्या?",
