        "workplace|3:1|5|title": "सरावाची फेरी",
        "workplace|3:1|5|scenario": "संजय पुण्यातल्या त्यांच्या ऑफिसमध्ये त्याची मॅनेजर लक्ष्मी हिच्यासोबत क्लायंटसाठीच्या सादरीकरणाचा सराव करतो.",
        "workplace|3:1|5|l0": "ठीक आहे संजय, समज मी क्लायंट आहे. तू तयार झालास की सुरू कर.",
        "workplace|3:1|5|l1": "सर्वांना सुप्रभात, आणि आम्हाला बोलावल्याबद्दल धन्यवाद. आज मी तुमच्या नव्या वेबसाइटसाठीची आमची योजना तुम्हाला समजावून सांगणार आहे.",
        "workplace|3:1|5|l2": "छान सुरुवात. भाषणाची मांडणी कशी करणार आहेस?",
        "workplace|3:1|5|l3": "मी तीन गोष्टी सांगेन: आम्हाला काय आढळलं, आम्ही काय सुचवतो, आणि त्याला किती खर्च येईल.",
        "workplace|3:1|5|l4": "छान आणि स्पष्ट. क्लायंटने मध्येच प्रश्न विचारून थांबवलं तर?",
        "workplace|3:1|5|l5": "मी त्यांचे आभार मानेन, प्रश्न लिहून घेईन आणि सांगेन की शेवटी त्यावर परत येतो.",
        "workplace|3:1|5|l6": "छान. आणि तुझ्या शेवटच्या स्लाइडवर काय आहे?",
        "workplace|3:1|5|l7": "तीन मुद्द्यांचा सारांश आणि पुढची स्पष्ट पायरी: पुढच्या शुक्रवारी एक मीटिंग.",
        "workplace|3:1|5|l8": "उत्तम. फक्त थोडं सावकाश बोल, आणि स्क्रीनकडे नाही, श्रोत्यांकडे बघ.",
        "workplace|3:1|5|l9": "धन्यवाद, लक्ष्मी. आज रात्री मी अजून एकदा सराव करेन.",
        "workplace|3:1|5|q0": "संजय कशाचं सादरीकरण करतोय?",
