        "workplace|4:1|0|w5": "प्रात्यक्षिक",
        "workplace|4:1|1|p0": "आम्ही काही सुचवण्याआधी, तुमच्या गरजांबद्दल आणखी सांगाल का?",
        "workplace|4:1|1|p1": "गुरुवारपर्यंत आम्ही तुम्हाला सविस्तर प्रस्ताव आणि दरपत्रक पाठवू.",
        "workplace|4:1|1|p2": "आमचं अंदाजे वेळापत्रक सहा आठवड्यांचं आहे, पण जागा पाहिल्यावर मी नक्की सांगेन.",
        "workplace|4:1|1|p3": "तुमच्यासाठी कोणता प्लॅन योग्य आहे, हे ठरवायला एखादं छोटं प्रात्यक्षिक उपयोगी पडेल का?",
        "workplace|4:1|1|p4": "या क्लायंटला ॲपच्या स्क्रीनसकट सगळं कन्नडमध्ये हवं आहे.",
        "workplace|4:1|2|w0": "रवाना करणे",
