        "workplace|4:1|2|w5": "खात्री देणे",
        "workplace|4:1|3|p0": "तुमची ऑर्डर सोमवारी आमच्या पुण्याच्या गोदामातून रवाना होईल.",
        "workplace|4:1|3|p1": "इनव्हॉइसवर चुकीची रक्कम आहे, म्हणून मी अकाउंट्सला ती दुरुस्त करायला सांगतो.",
        "workplace|4:1|3|p2": "तुमचा वैताग मी समजू शकतो, आणि आजच हे माझ्या मॅनेजरकडे नेतो.",
        "workplace|4:1|3|p3": "उशिराची भरपाई म्हणून या वेळी आम्ही डिलिव्हरी चार्ज माफ करू.",
        "workplace|4:1|3|p4": "मी तुम्हाला खात्री देतो की बदली वस्तू शुक्रवारपर्यंत तुमच्यापर्यंत पोहोचेल; हे माझं वैयक्तिक वचन आहे.",
        "workplace|4:1|4|title": "कधीच न आलेली मेन्यू कार्ड्स",
        "workplace|4:1|4|text": "इम्रान बंगळुरूमधल्या एका छपाई कंपनीत क्लायंटची खाती सांभाळतो. एका सोमवारी म्हैसूरमध्ये हॉटेल चालवणाऱ्या श्रीमती शेट्टी यांनी खूप नाराज होऊन त्याला फोन केला. दरपत्रकात आठवड्याभरात डिलिव्हरीचं आश्वासन दिलं असूनही त्यांची नवी मेन्यू कार्ड्स आली नव्हती. इम्रानने मध्ये न बोलता सगळं ऐकून घेतलं आणि मग नीट समजलंय याची खात्री करण्यासाठी त्यांच्या गरजा पुन्हा सांगितल्या. त्याला कळलं की इनव्हॉइसमधल्या एका चुकीमुळे ऑर्डर कधी रवानाच झाली नव्हती. त्याने ही अडचण मॅनेजरकडे नेली आणि त्याच दुपारी कुरिअरची व्यवस्था केली. उशिराची भरपाई म्हणून कंपनीने बिलात दहा टक्के सूट दिली. इम्रानने त्यांना खात्री दिली की पुढच्या ऑर्डर्स तो स्वतः तपासेल, आणि श्रीमती शेट्टी कंपनीसोबतच राहिल्या.",
        "workplace|4:1|4|q0": "श्रीमती शेट्टी नाराज का होत्या?",
        "workplace|4:1|4|q0o0": "त्यांची मेन्यू कार्ड्स आली नव्हती",
        "workplace|4:1|4|q0o1": "कार्ड्सवर शुद्धलेखनाच्या चुका होत्या",
