        "workplace|4:1|4|q2o2": "नवा प्रिंटर पाठवला",
        "workplace|4:1|4|q2o3": "त्यांचे सगळे पैसे परत केले",
        "workplace|4:1|5|title": "नवा क्लायंट",
        "workplace|4:1|5|scenario": "हुबळीतल्या एका फर्निचर कंपनीतली सेल्स मॅनेजर नेहा, नव्या ऑफिससाठी फर्निचर हवं असलेल्या विक्रम कुलकर्णी यांचा फोन घेते.",
        "workplace|4:1|5|l0": "नमस्कार कुलकर्णी साहेब. संपर्क केल्याबद्दल धन्यवाद. आम्ही काय मदत करू शकतो?",
        "workplace|4:1|5|l1": "आम्ही बेळगावमध्ये नवं ऑफिस सुरू करतोय, आणि आम्हाला चाळीस लोकांसाठी टेबलं आणि खुर्च्या हव्या आहेत.",
        "workplace|4:1|5|l2": "छान. तुमच्या गरजांबद्दल थोडं आणखी सांगाल का? तुमच्या मनात काही बजेट किंवा शैली आहे का?",
        "workplace|4:1|5|l3": "काहीतरी साधं आणि आरामदायक. आमचं बजेट साधारण आठ लाख रुपये आहे.",
        "workplace|4:1|5|l4": "हे सहज जमण्यासारखं आहे. तुम्हाला सगळ्याची डिलिव्हरी कधीपर्यंत हवी आहे?",
        "workplace|4:1|5|l5": "पुढच्या महिन्याच्या पंधरा तारखेपर्यंत. ती तारीख आमच्यासाठी खूप महत्त्वाची आहे.",
        "workplace|4:1|5|l6": "समजलं. मी शुक्रवारपर्यंत तुम्हाला दोन पर्यायांचा प्रस्ताव आणि दरपत्रक पाठवते.",
        "workplace|4:1|5|l7": "तुमची टीम जागेवर फर्निचर बसवण्याचं कामही करेल का?",
        "workplace|4:1|5|l8": "हो, बसवण्याचं काम त्यातच धरलेलं आहे. आणि आम्ही तुमची मुदत नक्की पाळू, याची मी खात्री देते.",
        "workplace|4:1|5|l9": "छान. मग मी तुमच्या प्रस्तावाची वाट पाहतो.",
        "workplace|4:1|5|q0": "फर्निचर किती लोकांसाठी आहे?",
