        "workplace|5:1|0|w4": "गैरहजर",
        "workplace|5:1|0|w5": "घरून काम करणे",
        "workplace|5:1|1|p0": "मला खूप ताप आलाय, म्हणून आज मला आजारपणाची रजा घ्यायची आहे.",
        "workplace|5:1|1|p1": "भावाच्या कॉलेज ॲडमिशनसाठी मी शुक्रवारी अर्धा दिवस रजा घेऊ शकतो का?",
        "workplace|5:1|1|p2": "ट्रेनची तिकिटं काढण्याआधी मी माझी शिल्लक रजा तपासतो.",
        "workplace|5:1|1|p3": "माझ्या मॅनेजरनी दहा ते चौदा तारखेपर्यंतची माझी रजा मंजूर केली आहे.",
        "workplace|5:1|1|p4": "सोमवारी मी गैरहजर होतो, त्याबद्दल माफ करा; राहिलेलं काम पूर्ण करायला उद्या घरून काम करू का?",
        "workplace|5:1|2|w0": "अदलाबदल करणे",
        "workplace|5:1|2|w1": "दुसऱ्याचं काम सांभाळणे",
        "workplace|5:1|2|w2": "कामाचं हस्तांतरण",
        "workplace|5:1|2|w3": "वेळ बदलणे",
        "workplace|5:1|2|w4": "लवचीक",
        "workplace|5:1|2|w5": "आधीच",
        "workplace|5:1|3|p0": "पुढच्या शनिवारी माझ्याशी शिफ्टची अदलाबदल करायला तुमची हरकत आहे का?",
        "workplace|5:1|3|p1": "मी नसताना माझे कॉल सांभाळायला प्रिया तयार झाली आहे.",
        "workplace|5:1|3|p2": "काहीही सुटू नये म्हणून मी गुरुवारी कामाचं नीट हस्तांतरण करेन.",
        "workplace|5:1|3|p3": "आपली आढावा बैठक पुढच्या आठवड्यात हलवू शकतो का? मी सोमवारी रजेवर आहे.",
        "workplace|5:1|3|p4": "किमान आठवडाभर आधी विचारलं, तर आमचे मॅनेजर लवचीक असतात.",
        "workplace|5:1|4|title": "उडुपीतलं लग्न",
        "workplace|5:1|4|text": "सौम्या बंगळुरूमध्ये एका बँकेच्या मुख्य कार्यालयात पेमेंट्स टीममध्ये काम करते. तिच्या चुलतबहिणीचं उडुपीतलं लग्न मार्चच्या शेवटच्या आठवड्यात, म्हणजे वर्षातल्या सगळ्यात गडबडीच्या काळात आलं. तिने तिची शिल्लक रजा तपासली, तेव्हा तिच्याकडे अजून नऊ दिवस होते. तीन आठवडे आधीच तिने तिचे मॅनेजर श्री. भट यांच्याकडे चार दिवसांची रजा मागितली आणि नम्रपणे कारण सांगितलं. लग्नाच्या दुसऱ्या दिवशी घरून काम करायचीही तयारी तिने दाखवली. श्री. भट लवचीक होते, पण त्यांनी विचारलं की महिनाअखेरचे रिपोर्ट्स कोण सांभाळेल. सौम्याने तिचा सहकारी राकेश याच्याशी दोन शिफ्टची अदलाबदल केली आणि जाण्याआधी कामाचं पूर्ण हस्तांतरण करायचं वचन दिलं. तिच्या नियोजनावर खूश होऊन श्री. भट यांनी त्याच दुपारी रजा मंजूर केली.",
        "workplace|5:1|4|q0": "सौम्याला रजा का हवी होती?",
