        "workplace|5:1|5|title": "भल्या सकाळचा फोन",
        "workplace|5:1|5|scenario": "अरुणची आई आजारी आहे, म्हणून तो भल्या सकाळी त्याची टीम लीड शालिनी हिला फोन करतो.",
        "workplace|5:1|5|l0": "सुप्रभात, शालिनी. इतक्या लवकर फोन केल्याबद्दल माफ करा. तुमच्याकडे एक मिनिट आहे का?",
        "workplace|5:1|5|l1": "हो, अरुण. सगळं ठीक आहे ना?",
        "workplace|5:1|5|l2": "तसं नाही. काल रात्री माझी आई पडली, आणि काही तपासण्यांसाठी मला तिला हॉस्पिटलमध्ये न्यायचं आहे.",
        "workplace|5:1|5|l3": "अरेरे, ऐकून वाईट वाटलं. तिची नीट काळजी घ्या. तुम्हाला पूर्ण दिवस लागेल का?",
        "workplace|5:1|5|l4": "मला वाटतं हो. आज मला रजा घ्यायची आहे, आणि कदाचित उद्या घरून काम करेन.",
        "workplace|5:1|5|l5": "चालेल. तीन वाजताच्या क्लायंट कॉलचं काय?",
        "workplace|5:1|5|l6": "दीपकला प्रोजेक्ट नीट माहीत आहे. मी त्याला आधीच विचारलं आहे, आणि तो आनंदाने कॉल सांभाळेल.",
        "workplace|5:1|5|l7": "छान. कृपया तुमच्या नोट्स त्याला पाठवा, आणि वेळ मिळेल तेव्हा पोर्टलवर रजेचा अर्ज करा.",
        "workplace|5:1|5|l8": "तासाभरात करतो. समजून घेतल्याबद्दल धन्यवाद, शालिनी.",
        "workplace|5:1|5|l9": "काही हरकत नाही. तुमच्या आईला लवकर बरं वाटो.",
        "workplace|5:1|5|q0": "अरुणला रजा का हवी आहे?",
