        "workplace|6:1|0|w5": "महत्त्वाचा टप्पा",
        "workplace|6:1|1|p0": "एकूणच, या वर्षी तुमची कामगिरी खूप चांगली झाली आहे.",
        "workplace|6:1|1|p1": "चिडलेल्या ग्राहकांशी तुम्ही ज्या शांतपणे वागता, ते तुमचं सगळ्यात मोठं बलस्थान आहे.",
        "workplace|6:1|1|p2": "कालच्या सादरीकरणाबद्दल मी तुम्हाला काही विधायक सूचना देऊ का?",
        "workplace|6:1|1|p3": "माझ्या स्वमूल्यांकनात मी वेळेचं नियोजन ही माझी कमकुवत बाजू म्हणून नोंदवली आहे.",
        "workplace|6:1|1|p4": "म्हैसूर शाखा वेळेवर सुरू करणं हा आमच्या टीमसाठी खरा महत्त्वाचा टप्पा होता.",
        "workplace|6:1|2|w0": "मार्गदर्शक",
        "workplace|6:1|2|w1": "नवी कौशल्यं शिकणे",
