        "workplace|6:1|2|w3": "क्षमता",
        "workplace|6:1|2|w4": "पगारवाढ",
        "workplace|6:1|2|w5": "पात्र असणे",
        "workplace|6:1|3|p0": "मला डेटा विश्लेषणात नवी कौशल्यं शिकायची आहेत; कंपनी एखाद्या छोट्या कोर्ससाठी मदत करू शकेल का?",
        "workplace|6:1|3|p1": "लीडच्या पदासाठी अर्ज करण्याआधी क्लाउडचं प्रमाणपत्र मिळवावं, असं माझ्या मार्गदर्शकांनी सुचवलं.",
        "workplace|6:1|3|p2": "तुमच्या मॅनेजरना वाटतं की दोन वर्षांत टीमचं नेतृत्व करण्याची क्षमता तुमच्यात आहे.",
        "workplace|6:1|3|p3": "या वर्षी टीममधल्या सगळ्यांना किमान आठ टक्के पगारवाढ मिळेल.",
        "workplace|6:1|3|p4": "मला वाटतं मी बढतीसाठी पात्र आहे, आणि पुढची पायरी काय आहे यावर मला चर्चा करायची आहे.",
        "workplace|6:1|4|title": "मूल्यांकनाचा दिवस",
        "workplace|6:1|4|text": "दर एप्रिलमध्ये मंगळुरूमधल्या फरीदाच्या कंपनीत वार्षिक मूल्यांकनाच्या बैठका होतात. तिच्या बैठकीआधी तिने प्रामाणिक स्वमूल्यांकन लिहिलं, ज्यात तिने तिची बलस्थानं आणि एक स्पष्ट कमकुवत बाजू नोंदवली: ती क्वचितच मदत मागायची. तिचे मॅनेजर श्री. राव यांनी सुरुवातीला नव्या बिलिंग सिस्टीमवरच्या तिच्या कामगिरीचं कौतुक केलं, जो टीमसाठी एक मोठा महत्त्वाचा टप्पा होता. मग त्यांनी अडचणी लवकर सांगण्याबद्दल तिला काही विधायक सूचना दिल्या. फरीदाने त्यांचे आभार मानले आणि प्रोजेक्ट मॅनेजमेंटच्या प्रशिक्षणाची मागणी केली. श्री. राव यांनी प्रमाणपत्र कोर्सचा खर्च करायचं आणि तिच्यासाठी एक वरिष्ठ मार्गदर्शक शोधायचं मान्य केलं. ते म्हणाले की तिच्यात एक दिवस टीमचं नेतृत्व करण्याची क्षमता आहे आणि ती चांगल्या पगारवाढीसाठी पात्र आहे. पुढच्या वर्षासाठी स्पष्ट योजना घेऊन फरीदा बैठकीतून बाहेर पडली.",
        "workplace|6:1|4|q0": "फरीदाने कोणती कमकुवत बाजू लिहिली?",
        "workplace|6:1|4|q0o0": "ती क्वचितच मदत मागायची",
        "workplace|6:1|4|q0o1": "ती अनेकदा उशिरा यायची",
        "workplace|6:1|4|q0o2": "ती खूप भरभर बोलायची",
        "workplace|6:1|4|q0o3": "ती बिलिंगमध्ये चुका करायची",
